data.command:
get registry value
 where key = 'CLUSTER'
   and subkey = 'jgroups-tcp-hosts'
|
if (@value is null)
{
    /* This is non-cluster environment so proceed with the self-heal */
    [select *
       from poldat
      where polcod = 'BY-VALIDATE'
        and polvar = 'MISCELLANEOUS'
        and polval = 'TASK-SELF-HEAL'
        and rownum < 2
      ORDER BY moddte DESC] catch(-1403)
    |
    if (@? = -1403)
    {
        /* Policy are not present in this instance, Create the policy */
        create policy
         where polcod = 'BY-VALIDATE'
           and polvar = 'MISCELLANEOUS'
           and polval = 'TASK-SELF-HEAL-DEVICE'
           and rtnum1 = 1
        |
        create policy
         where polcod = 'BY-VALIDATE'
           and polvar = 'MISCELLANEOUS'
           and polval = 'TASK-SELF-HEAL'
           and rtnum1 = 1
        |
        create policy
         where polcod = 'BY-VALIDATE'
           and polvar = 'MISCELLANEOUS'
           and polval = 'TASK-SELF-HEAL-INTERVAL-MINUTE'
           and rtnum1 = 10
        |
        publish data
         where result = 'Task Self-heal policy has been created, please re-run the self-heal logic'
    }
    else if (@? = 0 and @rtnum1 != 1)
    {
        /* Self-heal policy is available but disabled, please check with customer and mark as enable*/
        publish data
         where result = 'Task Self-heal policy is available but in disabled mode, please check with customer and mark as enable'
    }
    else if (@? = 0 and @rtnum1 = 1)
    {
        /*Task self-heal policy are available and enabled, validate the PURGE-TASK-EXECUTIONS job*/
        [select *
           from job_definition
          where command like '%remove task execution%'
            and job_id like '%PURGE-TASK%'
            and enabled = 1] catch(-1403)
        |
        if (@? = 0)
        {
            /* Task Self-heal policy is enable and having correct config for PURGE-TASK-EXECUTIONS */
            /*Create the by_validate table if not exits */
            [IF not EXISTS(SELECT 1
                             FROM sys.columns
                            WHERE Name = 'trigger_alert'
                              AND Object_ID = Object_ID('by_validate')) CREATE TABLE by_validate(validation_date datetime not NULL, job_id VARCHAR(256), problem VARCHAR(300), trigger_alert Int)]
            |
            {
                [select task_id,
                        auto_start,
                        restart
                   from task_definition
                  where restart = /*#nobind*/ 1 /*#bind*/] catch(-1403)
                |
                if (@auto_start = 0)
                {
                    [select max(start_dte) max_strdte,
                            max(end_dte) max_enddte
                       from task_definition_exec
                      where task_id = @task_id
                     having max(start_dte) > sysdate -0.0416] catch(-1403)
                    |
                    if (@? = 0)
                    {
                        publish data
                         where need_to_validate = 1
                    }
                }
                else if (@auto_start = 1)
                {
                    publish data
                     where need_to_validate = 1
                }
                |
                if (@need_to_validate = 1)
                {
                    /*validate var task eligible for self heal */
                    publish data
                     where time_interval = 1 / 24
                       and time_interval_device = 4 / 24
                       and task_id = @task_id
                    |
                    [select count(*) self_healed_count
                       from by_validate
                      where job_id = @task_id
                        and problem like '%self heal%'
                        and validation_date > sysdate - @time_interval]
                    |
                    if (@self_healed_count = 0)
                    {
                        list policies
                         where polcod = 'BY-VALIDATE'
                           and polvar = 'MISCELLANEOUS'
                           AND polval = 'TASK-SELF-HEAL-DEVICE'
                           and rtnum1 = 1
                           and rownum < 2 catch(-1403)
                        |
                        if (@? = 0)
                        {
                            publish data
                             where task_id_lower = lower(@task_id)
                            |
                            if (@task_id_lower like '%mtf%' or @task_id_lower like '%voice%' or @task_id_lower like '%mobile%')
                            {
                                [select count(*) task_restart_count
                                   from task_definition_exec
                                  where task_id = @task_id
                                    and end_dte > sysdate - @time_interval_device]
                                |
                                if (@task_restart_count = 0)
                                {
                                    publish data
                                     where can_we_auto_heal = "YES"
                                }
                                else
                                {
                                    publish data
                                     where can_we_auto_heal = "NO"
                                }
                            }
                            else
                            {
                                publish data
                                 where can_we_auto_heal = "YES"
                            }
                        }
                        else
                        {
                            publish data
                             where can_we_auto_heal = "NO"
                        }
                    }
                    else
                    {
                        publish data
                         where can_we_auto_heal = "NO"
                    }
                    |
                    if (@can_we_auto_heal = 'YES')
                    {
                        /*execute start task*/
                        publish data
                         where task_id = @task_id
                        |
                        [[import com.redprairie.moca.server.ServerUtils;import com.redprairie.moca.server.exec.SystemContext;import com.redprairie.moca.task.TaskManager;SystemContext sys = ServerUtils.globalContext();TaskManager _taskManager = (TaskManager) sys.getAttribute(TaskManager.ATTRIBUTE_NAME);if(!_taskManager.isRunning(task_id)){ _taskManager.startTask(task_id);return 0}else{return 1} ]]
                        |
                        if (@result = 0)
                        {
                            create record
                             where table_name = 'by_validate'
                               and validation_date = sysdate
                               and job_id = @task_id
                               and problem = 'Task configured as auto start but actually not running, self healed by logic'
                               and trigger_alert = 0
                        }
                    }
                }
            } >> res_config
            |
            list policies
             where polcod = 'BY-VALIDATE'
               and polvar = 'MISCELLANEOUS'
               and polval = 'TASK-SELF-HEAL-INTERVAL-MINUTE'
               and rownum < 2 catch(-1403)
            |
            if (@rtnum1 > 10)
            {
                publish data
                 where time_interval = @rtnum1 / 1440
            }
            else
            {
                publish data
                 where time_interval = 10 / 1440
            }
            |
            {
                [select count(*) dwld_id_count,
                        sys_id
                   from sl_dwnld
                  where dwnld_stat_cd = /*#nobind*/ 'ID' /*#bind*/
                    and ins_dt > sysdate -1
                  group by sys_id] catch(-1403)
                |
                if (@dwld_id_count > 60)
                {
                    /* Validate, either system has processed any download with in the defined internal of TASK-SELF-HEAL-INTERVAL-MINUTE */
                    [select count(*) processed_dwnld,
                            @sys_id
                       from sl_dwnld
                      where dwnld_stat_cd not in ('ID', 'NEW')
                        and sys_id = @sys_id
                        and last_upd_dt > sysdate - @time_interval] catch(-1403)
                    |
                    if (@processed_dwnld = 0)
                    {
                        /* identify all DownloadRunnerMain tasks for specific SYS_ID which could not processed in TASK-SELF-HEAL-INTERVAL-MINUTE and also union with generic if those are enable */
                        [select task_id action_task_id
                           from task_definition
                          where (cmd_line like '%DownloadRunnerMain%' or cmd_line like '%InboundAdapterRunnerMain%')
                            and cmd_line like '%' || @sys_id || '%'
                            and auto_start = /*#nobind*/ 1 /*#bind*/
                         union
                         select task_id action_task_id
                           from task_definition
                          where (cmd_line like '%DownloadRunnerMain%' or cmd_line like '%InboundAdapterRunnerMain%')
                            and (task_id like '%SL_DOWNLOAD%' or task_id like '%SL_INAD%')
                            and auto_start = /*#nobind*/ 1 /*#bind*/] catch(-1403)
                    }
                }
            } >> res_dwnld_id
            |
            /*All outbound events stuck in 'EC' status and unable to move to IC */
            {
                [select count(*) EC_Event_Count
                   from sl_evt_data
                  where evt_stat_cd = /*#nobind*/ 'EC' /*#bind*/
                    and ins_dt > sysdate - 1] catch(-1403)
                |
                if (@EC_Event_Count > 60)
                {
                    /* Validate, either system has processed any event with in the defined internal of TASK-SELF-HEAL-INTERVAL-MINUTE */
                    [select count(*) processed_evt
                       from sl_evt_data
                      where last_upd_dt > sysdate - @time_interval] catch(-1403)
                    |
                    if (@processed_evt = 0)
                    {
                        /* identify all IFDCreatorRunnerMain task */
                        [select task_id action_task_id
                           from task_definition
                          where cmd_line like '%IFDCreatorRunnerMain%'
                            and auto_start = /*#nobind*/ 1 /*#bind*/] catch(-1403)
                    }
                }
            } >> res_evt_ec
            |
            {
                [select count(*) IC_Event_Count,
                        sys_id
                   from sl_evt_data
                  where evt_stat_cd = /*#nobind*/ 'IC' /*#bind*/
                    and ins_dt > sysdate - 1
                  group by sys_id] catch(-1403)
                |
                if (@IC_Event_Count > 60)
                {
                    /* Validate, either system has processed any event with in the defined internal of TASK-SELF-HEAL-INTERVAL-MINUTE */
                    [select count(*) processed_evt,
                            @sys_id
                       from sl_evt_data
                      where evt_stat_cd in ('SC', 'SE')
                        and sys_id = @sys_id
                        and last_upd_dt > sysdate - @time_interval] catch(-1403)
                    |
                    if (@processed_evt = 0)
                    {
                        /* identify all IFDSenderRunnerMain tasks for specific SYS_ID which could not processed in TASK-SELF-HEAL-INTERVAL-MINUTE and also union with generic if those are enable */
                        [select sys_id hdr_sys_id
                           from sl_ifd_data_hdr
                          where evt_data_seq = (select min(evt_data_seq)
                                                  from sl_evt_data
                                                 where evt_stat_cd = /*#nobind*/ 'IC' /*#bind*/
                                                   and ins_dt > sysdate - 1
                                                   and sys_id = @sys_id)] catch(-1403)
                        |
                        if (@hdr_sys_id is not null)
                        {
                            [select task_id action_task_id
                               from task_definition
                              where cmd_line like '%IFDSenderRunnerMain%'
                                and cmd_line like '%' || @hdr_sys_id || '%'
                                and auto_start = /*#nobind*/ 1 /*#bind*/
                             union
                             select task_id action_task_id
                               from task_definition
                              where cmd_line like '%IFDSenderRunnerMain%'
                                and task_id like '%SL_IFDSENDER%'
                                and auto_start = /*#nobind*/ 1 /*#bind*/
                             union
                             select task_id action_task_id
                               from task_definition
                              where cmd_line like '%IFDSenderRunnerMain%'
                                and task_id in ('SL_IFDG_LM', 'SL_IFDG_LENS', 'SL_IFDG_DW', 'SL_IFDG_DUTY', 'MHE_IFDG_ASRS_OUT', 'MHE_IFDG_AGV_OUT', 'IFDGEN_TM', 'IFDGEN_JDA_CANONICAL')
                                and auto_start = /*#nobind*/ 1 /*#bind*/] catch(-1403)
                        }
                    }
                }
            } >> res_evt_ic
            |
            /*asynchronous event thread constantly examines the asynchronous event queue and logs events from the sl_async_evt_arg_data*/
            {
                [select count(*) async_pending_evt,
                        min(async_evt_que_seq) old_evt_seq
                   from sl_async_evt_que
                  where async_evt_stat_cd is null
                    and async_evt_dt > sysdate -1] catch(-1403)
                |
                if (@async_pending_evt > 99)
                {
                    go to sleep
                     where sleeptime = 20
                    |
                    [select count(*) async_pending_evt_now,
                            min(async_evt_que_seq) old_evt_seq_now
                       from sl_async_evt_que
                      where async_evt_stat_cd is null
                        and async_evt_dt > sysdate -1] catch(-1403)
                    |
                    if (@async_pending_evt_now > @async_pending_evt and @old_evt_seq = @old_evt_seq_now)
                    {
                        [select task_id action_task_id
                           from task_definition
                          where cmd_line like '%AsyncEventRunnerMain%'
                            and auto_start = /*#nobind*/ 1 /*#bind*/] catch(-1403)
                    }
                }
            } >> res_evt_async
            |
            if (rowcount(@res_dwnld_id) > 0 or rowcount(@res_evt_ec) > 0 or rowcount(@res_evt_ic) > 0 or rowcount(@res_evt_async) > 0)
            {
                publish data combination
                 where res = @res_dwnld_id
                   and res = @res_evt_ec
                   and res = @res_evt_ic
                   and res = @res_evt_async
                |
                publish data
                 where last_heal_time = 1 / 24
                |
                [select count(*) self_healed_count
                   from by_validate
                  where job_id = @action_task_id
                    and problem like '%self heal%'
                    and validation_date > sysdate - @last_heal_time] catch(-1403)
                |
                if (@self_healed_count = 0)
                {
                    create record
                     where table_name = 'by_validate'
                       and validation_date = sysdate
                       and job_id = @action_task_id
                       and problem = 'Task was not working funcationally so restart as self heal'
                       and trigger_alert = 0
                    |
                    publish data
                     where task_to_heal = @action_task_id
                }
            } >> res_action_task_id
            |
            if (rowcount(@res_action_task_id) > 0)
            {
                publish data combination
                 where res = @res_action_task_id
                |
                [[
    import com.redprairie.moca.*;import com.redprairie.moca.util.*; import com.redprairie.moca.MocaResults;import com.redprairie.moca.server.ServerUtils;import com.redprairie.moca.server.exec.SystemContext;import com.redprairie.moca.task.TaskManager;SystemContext sys = ServerUtils.globalContext();while(res_action_task_id.next()){ TaskManager _taskManager = (TaskManager) sys.getAttribute(TaskManager.ATTRIBUTE_NAME); if (_taskManager.isRunning(task_to_heal)) { /* stop the task for res_action_task_id  */  _taskManager.stopTask(task_to_heal); /* sleep the session for 5 seconds */ sleep(5000); if (!_taskManager.isRunning(task_to_heal)) { /* start the task for res_action_task_id  */  _taskManager.startTask(task_to_heal); return 0; } } else { return 1 } }]]
            }
            |
            [select job_id
               from by_validate
              where validation_date > sysdate -0.00347222222
                and problem like '%self heal%'] catch(@?) >> res
            |
            if (rowcount(@res) > 0)
            {
                convert column results to string
                 where res = @res
                   and separator = ', '
                   and colnam = 'job_id'
                |
                publish data
                 where result = 'Task Self-heal logic has started/restarted the task_id: ' || @result_string || ' in last 5 minutes.'
            }
            else
            {
                publish data
                 where result = 'Task Self-heal logic ran fine and all tasks are running fine'
            }
        }
        else
        {
            publish data
             where result = 'PURGE-TASK-EXECUTIONS is not having the condition of end_dte, please check with customer and change job_id:PURGE-TASK-EXECUTIONS'
        }
    }
}
else
{
    /* This is cluster instance */
    publish data
     where error = 'Task Self-heal is not available on this cluster instance, please install the rollout solution'
}
|
[SELECT count(*) task_heal_count
   FROM by_validate
  WHERE validation_date >= (select max(start_dte)
                              from job_definition_exec
                             where job_id = 'BY-VALIDATE-HEAL-TASK'
                               and end_dte is null)]
|
if (@task_heal_count > 0)
{
    send email
     where mail_from = 'noreply@jdadelivers.com'
       and send_to = 'cx-wgs-wms@blueyonder.com;cx-wgs-wms-ind@blueyonder.com;Shrusti.Chapparbandi@blueyonder.com'
       and subject = 'Kenco -PR1-Alert for Self-Heal'
       and msg = ' BY-VALIDATE-HEAL-TASK has healed ' || @task_heal_count || 'task/s in last 30 minutes'
}

